import {UiParameters} from "filter_ace_inline/local/ui_parameters";
import {addUi} from "filter_ace_inline/local/display_ui";
import {setupFileHandler} from "filter_ace_inline/local/file_helpers";
import {getCDatatypeMode} from "filter_ace_inline/local/c_datatype_mode";
import {OUTPUT_TEXT_CLASS} from "filter_ace_inline/local/utils";
import {getString} from 'core/str';

// Compared numerically rather than with ===, because the PHP side's type varies: get_config()
// and filter_get_local_config() both yield the string "1", while an unset setting yields false.
// A strict === "1" would silently disable simplified mode if that ever became an int.
const SIMPLIFIED_MODE_ENABLED = 1;

// The legacy explicit opt-in classes. A single class matching one of these is not a language
// name, so it must never be routed through extractSimplifiedClassModeParameters() even when
// simplified mode is also enabled site-wide alongside older, explicitly-classed content.
const LEGACY_MARKER_CLASSES = ['ace-highlight-code', 'ace-interactive-code'];

// How long to wait, and how often to look, for Ace's modelist extension before giving up on it
// and falling back to ACE_MODE_MAP alone - see getKnownLanguages().
const MODELIST_TIMEOUT = 2000;
const MODELIST_POLL_INTERVAL = 50;

/**
 * True if this element carries an explicit ace-inline marker: a data-ace-*-code attribute or
 * one of the legacy opt-in classes.
 *
 * Explicit decoration always wins over simplified mode. On such an element the class is a real
 * HTML class - typically "language-x" from TinyMCE or a Markdown renderer, which is never a
 * valid Jobe or Ace language name - rather than a simplified-mode specifier, and any
 * data-* attributes on it (button-name, stdin-taid, prefix/suffix, ...) must still be honoured.
 * @param {HTMLElement} element The <pre> or <code> element being checked.
 * @return {bool}
 */
const hasExplicitMarker = (element) => {
    if (element.hasAttribute('data-ace-interactive-code') ||
            element.hasAttribute('data-ace-highlight-code') ||
            LEGACY_MARKER_CLASSES.some((cls) => element.classList.contains(cls))) {
        return true;
    }
    // A <code> inherits its <pre>'s decoration: the attributes are conventionally written on the
    // <pre> while the language class lands on the <code> (see tests/fixtures/tryittinydemo.txt),
    // so without this the <code> loop below would take the simplified path and drop them.
    const parent = element.parentNode;
    return element.nodeName === 'CODE' && parent !== null && parent.nodeName === 'PRE' &&
        hasExplicitMarker(parent);
};

/**
 * True if element is one half of a genuine <pre><code>...</code></pre> fence pair - the only
 * shape every real Simplified Mode authoring path (this plugin's own generators, TinyMCE's Code
 * sample, Markdown Extra's fenced blocks) ever produces. Unlike explicit decoration (checked by
 * hasExplicitMarker() above), Simplified Mode has no attribute of its own to opt in with - its
 * only signal is the class on an otherwise-ordinary <pre>/<code> - so without this, any classed
 * <pre> with no <code> inside it (e.g. a WYSIWYG table cell styled with a layout class) would be
 * misread as Simplified Mode syntax too.
 * @param {HTMLElement} element The <pre> or <code> element being checked.
 * @return {bool}
 */
const hasPreCodePair = (element) => {
    if (element.nodeName === 'PRE') {
        return element.children.length === 1 && element.children[0].nodeName === 'CODE';
    }
    return element.nodeName === 'CODE' && element.parentNode !== null && element.parentNode.nodeName === 'PRE';
};

/**
 * True if simplified mode is enabled and this element's class should be parsed as a bare or
 * colon-separated "language[:option:value...]" specifier rather than treated as a normal HTML
 * class.
 * @param {HTMLElement} element The <pre> or <code> element being checked.
 * @param {object} config The plugin configuration settings.
 * @param {Set} languages The language names simplified mode accepts (see getKnownLanguages()).
 * @return {bool}
 */
const isSimplifiedClassMode = (element, config, languages) =>
    Number(config.simplified_mode) === SIMPLIFIED_MODE_ENABLED &&
        element.classList.length === 1 && !hasExplicitMarker(element) &&
        hasPreCodePair(element) &&
        languages.has(element.classList[0].split(':')[0].toLowerCase());

const ACE_DARK_THEME = 'ace/theme/tomorrow_night';
const ACE_LIGHT_THEME = 'ace/theme/textmate';
const LINE_NUMBER_COL_WIDTH = 42; // Width of line number column in Ace render.
const ACE_MODE_MAP = { // Ace modes for various languages (default: use language name).
    'c': 'c_cpp',
    'cpp': 'c_cpp',
    'js': 'javascript',
    'nodejs': 'javascript',
    'c#': 'csharp',
    'octave': 'matlab',
    'c++': 'c_cpp',
    'python2': 'python',
    'python3': 'python',
    'markup': 'html'
};

// Lazily-built, memoised return value of getKnownLanguages(); null until Ace's modelist
// extension has actually been read.
let knownLanguages = null;

/**
 * Ace's modelist extension, if it has been loaded. Ace's own loader returns undefined for a
 * module it doesn't have, but be defensive about it throwing too.
 * @return {object|null} The modelist module, or null if it isn't available.
 */
const getAceModelist = () => {
    try {
        return (globalThis.ace && globalThis.ace.require &&
            globalThis.ace.require('ace/ext/modelist')) || null;
    } catch {
        return null;
    }
};

/**
 * The set of language names a Simplified Mode class specifier is allowed to start with: every
 * mode Ace itself knows about, plus the aliases ACE_MODE_MAP translates.
 *
 * Without this, simplified mode's opt-in test degenerates to "carries exactly one class", so any
 * ordinary styling class turns a plain preformatted block into an Ace editor - a
 * <pre class="tablecell"> in a table becomes a request for an editor in a language called
 * "tablecell", which Ace silently renders as unhighlighted plain text.
 *
 * qtype_coderunner's load_ace() (called from this filter's setup()) requests ext-modelist.js
 * alongside ace.js, but they are two separate script loads, so allow a short window for the
 * second one to arrive. Only a set built from a modelist that really did load is memoised; the
 * ACE_MODE_MAP-only fallback is deliberately not, so a later call can still get the full set.
 * @return {Promise<Set>} The acceptable language names, lower case.
 */
const getKnownLanguages = async() => {
    if (knownLanguages) {
        return knownLanguages;
    }
    const deadline = Date.now() + MODELIST_TIMEOUT;
    let modelist = getAceModelist();
    while (!modelist && Date.now() < deadline) {
        await new Promise(resolve => setTimeout(resolve, MODELIST_POLL_INTERVAL));
        modelist = getAceModelist();
    }
    const languages = new Set([...Object.keys(ACE_MODE_MAP), ...Object.values(ACE_MODE_MAP)]);
    if (modelist) {
        Object.keys(modelist.modesByName).forEach((name) => languages.add(name));
        knownLanguages = languages;
    }
    return languages;
};

/**
 * True if element carries an ace-interactive-code marker: the legacy class/attribute, or (in
 * Simplified Mode) an "interactive" token in its colon-separated class specifier.
 * @param {HTMLelement} element The <pre> or <code> element being checked.
 * @param {object} config The plugin configuration settings.
 * @param {Set} languages The language names simplified mode accepts (see getKnownLanguages()).
 * @return {bool}
 */
const isInteractiveElement = (element, config, languages) =>
    element.classList.contains('ace-interactive-code') ||
    element.hasAttribute('data-ace-interactive-code') ||
    (isSimplifiedClassMode(element, config, languages) &&
        element.classList[0].split(':').includes('interactive'));

/**
 * True if element carries an ace-highlight-code marker: the legacy class/attribute, or a
 * Simplified Mode class specifier (highlight is Simplified Mode's default, so any valid
 * specifier qualifies, not just ones with an explicit marker token).
 * @param {HTMLelement} element The <pre> or <code> element being checked.
 * @param {object} config The plugin configuration settings.
 * @param {Set} languages The language names simplified mode accepts (see getKnownLanguages()).
 * @return {bool}
 */
const isHighlightElement = (element, config, languages) =>
    element.classList.contains('ace-highlight-code') ||
    element.hasAttribute('data-ace-highlight-code') ||
    isSimplifiedClassMode(element, config, languages);

/**
 * Extract this element's UI parameters (Simplified Mode's colon-separated class specifier, or
 * the standard data-* attributes) and apply an Ace editor to targetPre.
 * @param {HTMLelement} element The <pre> or <code> element the parameters are read from.
 * @param {HTMLelement} targetPre The <pre> element to actually replace with an Ace editor -
 *     the same as element when element is itself a <pre>, or element's parent <pre> when
 *     element is a <code> fence.
 * @param {bool} isInteractive True for ace-interactive otherwise false.
 * @param {object} config The plugin configuration settings.
 * @param {Set} languages The language names simplified mode accepts (see getKnownLanguages()).
 */
const processAceElement = (element, targetPre, isInteractive, config, languages) => {
    const uiParams = new UiParameters(element);
    if (isSimplifiedClassMode(element, config, languages)) {
        uiParams.extractSimplifiedClassModeParameters(isInteractive, config, element.classList[0].split(":"));
    } else {
        uiParams.extractUiParameters(isInteractive, config);
    }
    applyToPre(targetPre, isInteractive, uiParams);
};

/**
 * Replace all <pre> and <code> elements in the document rooted at root that have
 * the given className or ace-inline attribute, with an Ace editor windows that display the
 * code in whatever language has been set.
 * @param {object} root The root of the HTML document to modify.
 * @param {object} config The plugin configuration settings.
 * @param {bool} scoped When true, scan only the fragments text_filter.php actually produced
 *     (marked with data-ace-inline-scan - see do_ace_editor()), not the whole document: content
 *     from other plugins, navigation, or anything else on the page was never something this
 *     filter touched and must never be considered. Falls back to the whole document if no marked
 *     fragment exists at all. Must be false (the default) for globalThis.applyAceInteractive(),
 *     the documented hook for dynamically generated content: that content was inserted directly
 *     into the DOM after the page had already loaded, so it never went through
 *     do_ace_editor() and is never marked, regardless of whether other, earlier content on the
 *     same page happens to be - scoping this call would silently stop finding it forever.
 */
export const applyAceAndBuildUi = async(root, config, scoped = false) => {
    const languages = await getKnownLanguages();
    const scanned = scoped ? root.querySelectorAll('[data-ace-inline-scan]') : [];
    const scopes = scanned.length ? Array.from(scanned) : [root];

    // Look for ace editor controls in the <pre> fench first.
    // Snapshot into a plain array: applyToPre() below can insert a new <pre> (the output box
    // addUi() builds) as a later sibling of the pre it's attached to, and getElementsByTagName's
    // collection is live - without this the loop would go on to process its own freshly-inserted
    // output box as if it were more content to highlight.
    const preElements = scopes.flatMap((scope) => Array.from(scope.getElementsByTagName('pre')));
    for (const pre of preElements) {
        if (pre.classList.contains(OUTPUT_TEXT_CLASS)) {
            continue;
        }
        const isInteractive = isInteractiveElement(pre, config, languages);
        const isHighlight = isHighlightElement(pre, config, languages);
        if ((isInteractive || isHighlight) && pre.style.display !== 'none') {
            processAceElement(pre, pre, isInteractive, config, languages);
        }
    }

    // Look for ace editor controls in the <code> fence, this should take priority over ace editor controls in the <pre> fence.
    const codeElements = scopes.flatMap((scope) => Array.from(scope.getElementsByTagName('code')));
    for (const code of codeElements) {
        if (code.parentNode !== null && code.parentNode.nodeName === 'PRE' && code.parentNode.style.display !== 'none') {
            const isInteractive = isInteractiveElement(code, config, languages);
            const isHighlight = isHighlightElement(code, config, languages);
            if (isInteractive || isHighlight) {
                processAceElement(code, code.parentNode, isInteractive, config, languages);
            }
        }
    }
};

/**
 * Wait for Ace editor to render its content layers.
 * @param {HTMLelement} editNode The div element managed by Ace editor.
 * @param {number} expectedLines The expected number of text lines to be rendered.
 * @param {number} timeout Timeout in milliseconds (default 2000).
 * @return {Promise} Resolves when ace_text-layer is rendered, rejects on timeout.
 */
const waitForAceRender = (editNode, expectedLines, timeout = 2000) => {
    // To reduce the risk of false positives, let's be happy with at most 3 rendered
    // lines since AFAIK any failures actually have zero rendered lines.
    expectedLines = Math.min(3, expectedLines);

    return new Promise((resolve, reject) => {
        const startTime = Date.now();

        const checkRendering = () => {
            // On a cold page load Ace's font-metrics measurement can still be pending when the
            // editor is first created, leaving the text layer unpainted even though resize() was
            // already called once. Re-poking resize() on each poll is a cheap way to self-heal
            // once those metrics become available, without weakening the render-detection check.
            if (editNode.env && editNode.env.editor) {
                editNode.env.editor.resize(true);
            }

            // Count the number of div.ace_line elements which represent the actual rendered lines
            const aceLines = editNode.querySelectorAll('div.ace_line');

            if (aceLines.length >= expectedLines) {
                // Successfully found the expected number of rendered lines
                resolve();
            } else if (Date.now() - startTime >= timeout) {
                // Timeout exceeded
                reject(new Error('Ace editor rendering timeout: ace_text-layer not populated'));
            } else {
                // Not ready yet, check again soon
                setTimeout(checkRendering, 50);
            }
        };

        checkRendering();
    });
};

/**
 * Replace the given PRE element with an element managed by the Ace editor,
 * unless 'hidden' is true, in which case we just hide the PRE.
 * @param {HTMLelement} pre The PRE element to be be replaced by an Ace editor.
 * @param {bool} isInteractive True for ace-interactive otherwise false.
 * @param {Object} uiParameters the User Interface parameters for the element.
 */
const applyToPre = async(pre, isInteractive, uiParameters) => {
    const params = uiParameters.paramsMap;
    if (params['file-upload-id']) {
        setupFileHandler(params['file-upload-id']);
    }

    let editNode = null;
    let expectedLines = 0;
    if (!params.hidden) {
        // Count the number of lines in the original pre element
        const text = pre.textContent;
        const numLines = text.split("\n").length;
        const minLines = params['min-lines'];
        const maxLines = params['max-lines'];
        // Calculate expected lines: max(min-lines, min(numLines, max-lines))
        expectedLines = Math.max(minLines, Math.min(numLines, maxLines));
        editNode = await setUpAce(pre, uiParameters, isInteractive);
    } else if (isInteractive) { // Code is hidden but there's still a button to run it.
        const getCode = () => pre.innerText;
        addUi(pre, getCode, uiParameters);
    }

    // Wait for Ace to fully render before hiding the original pre element
    if (editNode) {
        try {
            await waitForAceRender(editNode, expectedLines);
            pre.style.display = 'none'; // NB this sets display = 'none', checked above.
        } catch (error) {
            // Remove the failed Ace editNode
            if (editNode.parentNode) {
                editNode.parentNode.removeChild(editNode);
            }

            // Create and insert warning message before pre
            const warningDiv = document.createElement('div');
            warningDiv.style.color = '#f44336';
            warningDiv.style.marginBottom = '2px';

            try {
                const str = await getString('error_ace_render_failed', 'filter_ace_inline');
                warningDiv.textContent = str;
            } catch {
                // Fallback if string loading fails
                warningDiv.textContent = 'Warning: Ace editor failed to render properly. Displaying plain text instead.';
            }

            pre.parentNode.insertBefore(warningDiv, pre);

            // Style the pre element to make it stand out
            pre.style.border = '2px solid #f44336';
            pre.style.padding = '10px';
            pre.style.display = 'block'; // Ensure it's visible
        }
    } else {
        pre.style.display = 'none';
    }
};

/**
 * Sets up Ace with all its parameters and adds a button if interactive.
 * @param {HTMLelement} pre The pre element that the Ace editor is replacing.
 * @param {Object} uiParameters The UI parameters from the Pre element + defaults.
 * @param {bool} isInteractive True if the code is interactive.
 * @return {HTMLelement} The editNode div element managed by Ace editor.
 */
const setUpAce = async(pre, uiParameters, isInteractive) => {
    const params = uiParameters.paramsMap;
    const darkMode = params['dark-theme-mode']; // 0, 1, 2 for never, sometimes, always
    let theme = null;
    // Use light or dark theme according to user's prefers-color-scheme.
    // Default to light.
    if (darkMode == 2 || (darkMode == 1 && globalThis.matchMedia &&
            globalThis.matchMedia("(prefers-color-scheme: dark)").matches)) {
        theme = ACE_DARK_THEME;
    } else {
        theme = ACE_LIGHT_THEME;
    }
    const showLineNumbers = params['start-line-number'] ? true : false;
    let aceLang = params['ace-lang'] ? params['ace-lang'] : params.lang;
    aceLang = aceLang.toLowerCase();
    if (aceLang in ACE_MODE_MAP) {
        aceLang = ACE_MODE_MAP[aceLang];
    }
    // The c_cpp mode gets a custom variant that additionally highlights
    // "_t"-suffixed and PascalCase identifiers as datatypes.
    const mode = aceLang === 'c_cpp' ? await getCDatatypeMode() : 'ace/mode/' + aceLang;
    const text = pre.textContent;
    const lines = text.split("\n");
    const numLines = lines.length;
    const longestLine = longest(lines);

    const editNode = document.createElement('div'); // Ace editor manages this
    editNode.style.margin = "6px 0px 6px 0px";
    editNode.style.lineHeight = "1.3";
    editNode.style.width = pre.style.width ? pre.style.width : "100%";
    editNode.style.minHeight = "30px"; // If Ace render fails, at least there's something there to click on!

    editNode.style.resize = "none";
    pre.after(editNode); // Insert the edit node

    let aceConfig = {
        newLineMode: "unix",
        mode: mode,
        minLines: Math.max(numLines, params['min-lines']),
        maxLines: params['max-lines'],
        fontSize: params['font-size'],
        showLineNumbers: showLineNumbers,
        firstLineNumber: params['start-line-number'],
        showGutter: showLineNumbers,
        showPrintMargin: false,
        autoScrollEditorIntoView: true,
        highlightActiveLine: showLineNumbers
    };

    const editor = globalThis.ace.edit(editNode, aceConfig);
    const session = editor.getSession();
    // Ace defers painting the text layer until it has measured font metrics; without
    // forcing a resize here it can be left blank when created on a freshly-inserted node.
    editor.resize(true);
    if (!pre.style.hasOwnProperty('width') || pre.style.width == 0) {
        const aceWidestLine = Math.ceil(lineLength(editor.renderer, longestLine));
        const minWidth = isInteractive ? aceWidestLine + LINE_NUMBER_COL_WIDTH : aceWidestLine;
        editNode.style.minWidth = minWidth + "px";
    }
    session.setValue(text);

    editor.setTheme(theme);
    if (params.readonly !== null) {
        editor.setReadOnly(true);
        editNode.classList.add('readonly'); // For CSS use.
    }

    // Add a button and text area for output if ace-interactive-code.
    if (isInteractive) {
        const getCode = () => editor.getSession().getValue();
        addUi(editNode, getCode, uiParameters);
    } else {
        editor.renderer.$cursorLayer.element.style.display = "none"; // Hide cursor.
    }

    return editNode;
};

/**
 * Return the length of the given line when rendered by the given Ace editor.
 * @param {Ace-renderer} renderer The Ace renderer.
 * @param {String} line The line whose length is being checked.
 * @return {int} The length of the rendered line in pixels.
 */
const lineLength = (renderer, line) => {
  const chars = renderer.session.$getStringScreenWidth(line)[0];
  const width = Math.max(chars, 2) * renderer.characterWidth + // Text size
    2 * renderer.$padding + // Padding
    2 + // Little extra for the cursor
    0; // Add border width if needed

  return width;
};

/**
 * Return the longest of an array of strings.
 * @param {array} lines An array of lines
 * @return {String} The longest of the lines
 */
const longest = (lines) => {
    let longest = '';
    for (const line of lines) {
        if (line.length > longest.length) {
            longest = line;
        }
    }
    return longest;
};
